"""Complete highest street fascia front rectangle; lower coplanar fascia neutral."""
from pathlib import Path
import numpy as np,trimesh,json,hashlib
R=Path(__file__).resolve().parent;H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();expected='68f9820b1aefd7a1cd90439c341ad73d366cc02e3bffc51ebb2bbc15adae6ef2';assert H(R/'model.stl')==expected
m=trimesh.load(R/'model.stl',force='mesh',process=True);assert len(m.faces)==12264
t=m.triangles;n=m.face_normals;e=.0001;a=np.full(len(t),1,np.int32);D={}
plane=np.flatnonzero(np.abs(t[:,:,1]+56).max(1)<1e-5);assert len(plane)==4
edges=m.face_adjacency;edges=edges[np.isin(edges[:,0],plane)&np.isin(edges[:,1],plane)]
pcs=trimesh.graph.connected_components(edges,nodes=plane,min_len=1);assert sorted(map(len,pcs))==[2,2]
chosen=[c for c in pcs if (t[c,:,2]>=53-1e-5).all()];assert len(chosen)==1
ids=chosen[0];assert len(ids)==2
D['complete_highest_street_fascia_front']=ids.tolist();a[ids]=0
ad=m.face_adjacency;cop=(n[ad[:,0]]*n[ad[:,1]]).sum(1)>.999999;cs=trimesh.graph.connected_components(ad[cop],nodes=np.arange(len(t)),min_len=1);assert all(len(set(a[c]))==1 for c in cs);assert np.bincount(a).tolist()==[2,12262]
pal=[('NYCU Chihyuan Co-Innovation observed highest street fascia front nominal lightgray','#C7CBC8'),('UNVERIFIED main walls entrance windows roofs neutral','#B8BAB5')]
np.savez_compressed(R/'color-mesh.npz',vertices=m.vertices,faces=m.faces,materials=a);(R/'palette.json').write_text(json.dumps(pal,indent=2)+'\n');q={'palette':[{'id':i,'name':name,'hex':col,'faces':int((a==i).sum())}for i,(name,col)in enumerate(pal)],'domain_face_indices':D,'coplanar_components':len(cs),'partial_color_incomplete':True,'fully_colored_exterior':False,'geometry_policy':'12264 original triangles unchanged','limits':['Lower floor fascia not selected here; no completeness claim from tree-obscured portions.', 'All window backs contain frames/reflections and remain neutral.', 'Whole main wall contains accent orange patches not separated by original topology; do not uniformly paint wall.', 'Opaque railing proxies are not actual metal rails.', 'Other upper fins, courtyard, chevron screen/yellow accents, columns, roofs, inner faces and unknown back domains remain neutral in this bounded recommendation.', '致遠樓產學共創中心 is not 智源共同合作中心. Do not double-count the platform in Chimei building.', 'Main twin wings with connected blocks/court/terraces are one existingmodel; no new building count.', 'Original incomplete inner-court evidence, approximate bridges/depth, thickened/flattened screen tips and railing proxies remain; no geometry correction.', 'Original317 sections and canonical thin v2 maximum0.311% opening loss preserved, not global minwall/physical-print certification.', 'No original package, STL/OBJ/Blend or historic previews overwritten. The old interrupted-source BLOCK is historical; no assertion that original package remains missing.']};(R/'appearance-materials.json').write_text(json.dumps(q,indent=2)+'\n');(R/'COLOR-ASSIGNMENT-QA.json').write_text(json.dumps({'status':'PASS','original_STL_sha256':expected,'triangles':12264,'color_mesh_sha256':H(R/'color-mesh.npz')},indent=2));print(q['palette'],'components',len(cs))
